-- runtime part 6: element search and menu blur.

-- ---- search: Library.SearchWindow(window, query) ----
-- Elements register their frame + name (Library.regSearch); a section whose NAME matches shows all its elements; otherwise only matching ones.
-- Pages with no match are dimmed in the sidebar; when the open page has no match the first page with one opens.
function Library.SearchWindow(window, query)
	query = tostring(query or ""):lower()
	local W = window._W
	local searching = query ~= ""
	local perSection, perPage, found = {}, {}, 0
	local nameMatch = {}
	for _, s in window.SectionList do nameMatch[s.section] = searching and s.name:lower():find(query, 1, true) ~= nil end
	for _, item in window.SearchItems do
		local match = (not searching) or nameMatch[item.section] or item.name:lower():find(query, 1, true) ~= nil
		if searching then
			if not item.hidden and not match then item.prev, item.hidden = item.root.Visible, true item.root.Visible = false
			elseif item.hidden and match then item.hidden = false item.root.Visible = item.prev ~= false end
		elseif item.hidden then
			item.hidden = false
			item.root.Visible = item.prev ~= false
		end
		if match and (not searching or item.root.Visible) then
			perSection[item.section] = true
			if searching and not nameMatch[item.section] then found += 1 end
		end
	end
	for _, s in window.SectionList do
		local show = (not searching) or perSection[s.section] or nameMatch[s.section]
		s.root.Visible = show and true or false
		if searching and show then perPage[s.page] = true if nameMatch[s.section] then found += 1 end end
	end
	local current
	for _, p in window.Pages do if p.Items["Page"].Instance.Visible then current = p end end
	local first
	for _, p in window.Pages do
		local has = (not searching) or perPage[p]
		local tab = p.Items["Inactive"].Instance
		local label = tab:FindFirstChild("label")
		if label then label.TextTransparency = has and 0 or 0.55 end
		if has and not first then first = p end
	end
	if searching and first and current and not perPage[current] then
		for _, p in window.Pages do p:Turn(p == first) end
	end
	W.pageTitle.Text = searching and (tostring(found) .. " found") or (current and current.Name or W.pageTitle.Text)
end

-- ---- menu blur + translucent window ----
Library.Blur = { Enabled = true, Size = 14, Transparency = 0.04 }
do
	local Lighting = game:GetService("Lighting")
	local effect = Instance.new("BlurEffect")
	effect.Name = "\0"
	effect.Size = 0
	effect.Enabled = true
	pcall(function() effect.Parent = Lighting end)
	function Library.UpdateBlur()
		local anyOpen = false
		for _, w in Library.Windows do if w.IsOpen then anyOpen = true end end
		local target = (Library.Blur.Enabled and anyOpen) and Library.Blur.Size or 0
		Library:TweenTo(effect, { Size = target }, 0.25)
		for _, w in Library.Windows do
			Library:TweenTo(w._W.Root, { BackgroundTransparency = Library.Blur.Enabled and Library.Blur.Transparency or 0 }, 0.25)
		end
	end
	function Library:SetBlur(enabled, size, transparency)
		Library.Blur.Enabled = enabled and true or false
		if size then Library.Blur.Size = size end
		if transparency then Library.Blur.Transparency = transparency end
		Library.UpdateBlur()
	end
	Library.OnUnload = Library.OnUnload or {}
	table.insert(Library.OnUnload, function() pcall(function() effect:Destroy() end) end)
	task.defer(Library.UpdateBlur)
end


